class Solution {
    static constexpr long long MOD = 1e9 + 7;
    vector<long long> sm, sq, lz;
    int n;
    void push(int o, int l, int r) {
        if (!lz[o]) return;
        int m = (l + r) / 2;
        long long v = lz[o];
        auto ap = [&](int c, int ln) {
            sq[c] = (sq[c] + v * v % MOD * ln + 2 * v % MOD * sm[c]) % MOD;
            sm[c] = (sm[c] + v * ln) % MOD;
            lz[c] = (lz[c] + v) % MOD;
        };
        ap(2 * o, m - l + 1); ap(2 * o + 1, r - m);
        lz[o] = 0;
    }
    void upd(int o, int l, int r, int a, int b, long long v) {
        if (b < l || r < a) return;
        if (a <= l && r <= b) {
            long long ln = r - l + 1;
            sq[o] = (sq[o] + v * v % MOD * ln + 2 * v % MOD * sm[o]) % MOD;
            sm[o] = (sm[o] + v * ln) % MOD;
            lz[o] = (lz[o] + v) % MOD;
            return;
        }
        push(o, l, r); int m = (l + r) / 2;
        upd(2 * o, l, m, a, b, v); upd(2 * o + 1, m + 1, r, a, b, v);
        sm[o] = (sm[2 * o] + sm[2 * o + 1]) % MOD;
        sq[o] = (sq[2 * o] + sq[2 * o + 1]) % MOD;
    }
public:
    int sumCounts(vector<int>& nums) {
        n = nums.size();
        sm.assign(4 * n, 0); sq.assign(4 * n, 0); lz.assign(4 * n, 0);
        unordered_map<int,int> last; long long ans = 0;
        for (int j = 0; j < n; j++) {
            upd(1, 0, n - 1, last.count(nums[j]) ? last[nums[j]] + 1 : 0, j, 1);
            ans = (ans + sq[1]) % MOD;
            last[nums[j]] = j;
        }
        return (int)ans;
    }
};

