class Solution {
    static final long MOD = 1_000_000_007L;
    long[] sm, sq, lz;
    int n;
    void push(int o, int l, int r) {
        if (lz[o] == 0) return;
        int m = (l + r) / 2; long v = lz[o];
        apply(2 * o, m - l + 1, v); apply(2 * o + 1, r - m, v);
        lz[o] = 0;
    }
    void apply(int c, int ln, long v) {
        sq[c] = (sq[c] + v * v % MOD * ln + 2 * v % MOD * sm[c]) % MOD;
        sm[c] = (sm[c] + v * ln) % MOD;
        lz[c] = (lz[c] + v) % MOD;
    }
    void upd(int o, int l, int r, int a, int b, long v) {
        if (b < l || r < a) return;
        if (a <= l && r <= b) { apply(o, r - l + 1, v); return; }
        push(o, l, r); int m = (l + r) / 2;
        upd(2 * o, l, m, a, b, v); upd(2 * o + 1, m + 1, r, a, b, v);
        sm[o] = (sm[2 * o] + sm[2 * o + 1]) % MOD;
        sq[o] = (sq[2 * o] + sq[2 * o + 1]) % MOD;
    }
    public int sumCounts(List<Integer> nums) {
        n = nums.size();
        sm = new long[4 * n]; sq = new long[4 * n]; lz = new long[4 * n];
        Map<Integer,Integer> last = new HashMap<>(); long ans = 0;
        for (int j = 0; j < n; j++) {
            upd(1, 0, n - 1, last.getOrDefault(nums.get(j), -1) + 1, j, 1);
            ans = (ans + sq[1]) % MOD;
            last.put(nums.get(j), j);
        }
        return (int) ans;
    }
}

