var sumCounts = function(nums) {
    const MOD = 1e9 + 7, n = nums.length;
    const sm = new Array(4 * n).fill(0), sq = new Array(4 * n).fill(0), lz = new Array(4 * n).fill(0);
    function apply(c, ln, v) {
        sq[c] = (sq[c] + v * v % MOD * ln + 2 * v * sm[c]) % MOD;
        sm[c] = (sm[c] + v * ln) % MOD;
        lz[c] = (lz[c] + v) % MOD;
    }
    function push(o, l, r) {
        if (!lz[o]) return;
        const m = (l + r) >> 1, v = lz[o];
        apply(2 * o, m - l + 1, v); apply(2 * o + 1, r - m, v);
        lz[o] = 0;
    }
    function upd(o, l, r, a, b, v) {
        if (b < l || r < a) return;
        if (a <= l && r <= b) { apply(o, r - l + 1, v); return; }
        push(o, l, r); const m = (l + r) >> 1;
        upd(2 * o, l, m, a, b, v); upd(2 * o + 1, m + 1, r, a, b, v);
        sm[o] = (sm[2 * o] + sm[2 * o + 1]) % MOD;
        sq[o] = (sq[2 * o] + sq[2 * o + 1]) % MOD;
    }
    const last = new Map(); let ans = 0;
    for (let j = 0; j < n; j++) {
        upd(1, 0, n - 1, (last.get(nums[j]) ?? -1) + 1, j, 1);
        ans = (ans + sq[1]) % MOD;
        last.set(nums[j], j);
    }
    return ans;
};
